(()=>{const $=s=>document.querySelector(s),questions=[['ease','지역을 선택하고 결과를 찾기 쉬웠나요?'],['understanding','저수율 변화와 주의 근거를 이해하기 쉬웠나요?'],['wouldUse','다음 관측일에 다시 사용할 의향이 있나요?']];$('#questions').innerHTML=questions.map(([key,label])=>`<label>${label}</label><div class="scale">${[1,2,3,4,5].map(n=>`<label><input required type="radio" name="${key}" value="${n}">${n}점</label>`).join('')}</div>`).join('');const render=m=>{$('#metrics').innerHTML=[['응답 수',m.responses+'건'],['사용 편의',m.averages.ease===null?'—':m.averages.ease+'/5'],['이해도',m.averages.understanding===null?'—':m.averages.understanding+'/5'],['재사용 의향',m.averages.wouldUse===null?'—':m.averages.wouldUse+'/5'],['협의 카드',m.cards.created30d+'건'],['확인 완료',m.cards.done+'건']].map(([a,b])=>`<article class="metric"><span>${a}</span><b>${b}</b></article>`).join('')};async function metrics(){try{const r=await fetch('/api/pilot/metrics'),m=await r.json();if(!r.ok)throw Error(m.error);render(m)}catch(e){$('#metrics').innerHTML='<p class="muted">지표를 불러오지 못했습니다.</p>'}}$('#form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),body=Object.fromEntries(f.entries()),state=$('#state');state.textContent='저장 중입니다.';try{const r=await fetch('/api/pilot/feedback',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)}),j=await r.json();if(!r.ok)throw Error(j.error);state.textContent='익명 피드백을 저장했습니다. 감사합니다.';state.className='ok';e.currentTarget.reset();render(j.metrics)}catch(err){state.textContent='저장하지 못했습니다: '+err.message;state.className='muted'}};metrics()})();
